BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';

-- Prevent accidental import into another database
DO $$
BEGIN
  IF current_database() <> 'pali_resort_staging' THEN
    RAISE EXCEPTION 'Wrong database';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.outlets
    WHERE id = 'rest-1'
      AND property_id = '752e7d93-13d1-4903-82fd-8aaf0c8e3feb'
      AND is_active = true
  ) THEN
    RAISE EXCEPTION 'Staging outlet verification failed';
  END IF;
END $$;



DO $$ BEGIN
  IF (SELECT COUNT(*) FROM public.menu_items mi JOIN public.menu_categories mc ON mc.id=mi.category_id WHERE mc.code LIKE 'PV236-CAT-%%') <> 236 THEN
    RAISE EXCEPTION 'Expected exactly 236 staged dishes';
  END IF;
END $$;
COMMIT;
